   142	func killPinnedMarkedProcess(pid int, entry []byte) error {
   143		fd, err := unix.PidfdOpen(pid, 0)
   144		if errors.Is(err, unix.ESRCH) {
   145			return nil
   146		}
   147		if err != nil {
   148			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
   149		}
   150		defer unix.Close(fd)
   151		// The pidfd names one process for its lifetime; if pid was reused before
   152		// it was opened, the new process does not carry this run's entry.
   153		marked, err := reviewProcessMarked(pid, entry)
