   233	// delegateUsage reports a usage error: exit 2, as text, or as the error
   234	// document when the caller asked for --json (R10).
   235	func delegateUsage(stdout, stderr io.Writer, args []string, command, msg string) int {
   236		for _, arg := range args {
   237			if arg == "--json" {
   238				writeDelegateJSON(stdout, map[string]any{"schema": delegateErrorSchema, "command": command, "error": msg, "usage": true})
