   246	func writeDelegateJSON(stdout io.Writer, doc any) {
   247		// Every error document a detached run writes is handed back (B03); a
   248		// caller that knows its exit code hands it back first.
   249		if m, ok := doc.(map[string]any); ok && m["schema"] == delegateErrorSchema {
   250			code := 1
   251			if m["usage"] == true {
   252				code = 2
   253			}
   254			handBackRefusal(m, code)
   255		}
   256		enc := json.NewEncoder(stdout)
   257		enc.SetIndent("", "  ")
   258		_ = enc.Encode(doc)
   259	}
