   208	func readShimProcStat(pid int) (shimProcStat, error) {
   209		raw, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
   210		if err != nil {
   211			return shimProcStat{}, err
   212		}
   213		text := string(raw)
   214		end := strings.LastIndexByte(text, ')')
   215		if end < 0 {
   216			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   217		}
   218		f := strings.Fields(text[end+1:])
   219		if len(f) < 2 {
   220			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   221		}
   222		ppid, err := strconv.Atoi(f[1])
   223		if err != nil {
   224			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   225		}
   226		return shimProcStat{ppid: ppid, zombie: f[0] == "Z"}, nil
   227	}
