   229	// killPinnedChild signals pid through a pidfd while it is still a child of
   230	// parent: a pid reused by an unrelated process is never signalled. It says
   231	// whether the signal reached the process; one that already ended was not
   232	// ended by the shim and is not reported (review round 11, N2).
   233	func killPinnedChild(pid, parent int) (bool, error) {
   234		fd, err := unix.PidfdOpen(pid, 0)
   235		if errors.Is(err, unix.ESRCH) {
   236			return false, nil
   237		}
   238		if err != nil {
   239			return false, fmt.Errorf("process %d could not be pinned: %w", pid, err)
   240		}
   241		defer unix.Close(fd)
   242		st, err := readShimProcStat(pid)
   243		if reviewProcessGoneErr(err) || err == nil && (st.ppid != parent || st.zombie) {
   244			return false, nil
