   270	// readProcBatched lists the numeric entries of /proc in batches, and stops
   271	// with an error once deadline passes.
   272	func readProcBatched(deadline time.Time) ([]os.DirEntry, error) {
   273		f, err := os.Open("/proc")
   274		if err != nil {
   275			return nil, fmt.Errorf("the run's processes could not be listed: %w", err)
   276		}
   277		defer f.Close()
   278		var out []os.DirEntry
   279		for {
   280			batch, err := f.ReadDir(512)
   281			for _, d := range batch {
   282				if d.Name()[0] >= '0' && d.Name()[0] <= '9' {
   283					out = append(out, d)
   284				}
   285			}
   286			if err != nil || len(batch) == 0 {
   287				return out, nil
   288			}
   289			if time.Now().After(deadline) {
   290				return out, fmt.Errorf("the run's processes could not be listed within the bound")
   291			}
   292		}
   293	}

