    84	// resumeProcessThreads resumes every thread of pid; a suspended process has
    85	// only its main thread.
    86	func resumeProcessThreads(pid uint32) error {
    87		snapshot, err := windows.CreateToolhelp32Snapshot(windows.TH32CS_SNAPTHREAD, 0)
    88		if err != nil {
    89			return err
    90		}
    91		defer windows.CloseHandle(snapshot)
    92		entry := windows.ThreadEntry32{Size: uint32(unsafe.Sizeof(windows.ThreadEntry32{}))}
    93		resumed := 0
    94		for err = windows.Thread32First(snapshot, &entry); err == nil; err = windows.Thread32Next(snapshot, &entry) {
    95			if entry.OwnerProcessID != pid {
    96				continue
    97			}
    98			thread, err := windows.OpenThread(windows.THREAD_SUSPEND_RESUME, false, entry.ThreadID)
    99			if err != nil {
   100				return err
   101			}
   102			_, rerr := windows.ResumeThread(thread)
   103			_ = windows.CloseHandle(thread)
   104			if rerr != nil {
   105				return rerr
   106			}
   107			resumed++
   108		}
   109		if resumed == 0 {
   110			return fmt.Errorf("no thread of process %d was found", pid)
   111		}
   112		return nil
   113	}
