   115	// terminateReviewJob ends every process of cmd's job and waits until the job
   116	// is empty.
   117	func terminateReviewJob(cmd *exec.Cmd) error {
   118		value, ok := reviewJobs.Load(cmd)
   119		if !ok {
   120			if cmd.Process != nil {
   121				return cmd.Process.Kill()
   122			}
   123			return nil
   124		}
   125		job := value.(windows.Handle)
   126		if err := windows.TerminateJobObject(job, 1); err != nil {
   127			return fmt.Errorf("the reviewer's job could not be terminated: %w", err)
   128		}
   129		deadline := time.Now().Add(reviewReapWait)
   130		for {
   131			var acct jobBasicAccounting
   132			if err := windows.QueryInformationJobObject(job, windows.JobObjectBasicAccountingInformation, uintptr(unsafe.Pointer(&acct)), uint32(unsafe.Sizeof(acct)), nil); err != nil {
   133				return fmt.Errorf("the reviewer's job could not be inspected: %w", err)
   134			}
   135			if acct.ActiveProcesses == 0 {
   136				return nil
   137			}
   138			if time.Now().After(deadline) {
   139				return fmt.Errorf("%d process(es) of the reviewer's job could not be ended", acct.ActiveProcesses)
   140			}
   141			time.Sleep(20 * time.Millisecond)
   142		}
   143	}
